 _matchClick(r,c){const s=this.state;if(!s.selected){s.selected=[r,c];return}const[a,b]=s.selected;if(Math.abs(a-r)+Math.abs(b-c)===1){[s.grid[a][b],s.grid[r][c]]=[s.grid[r][c],s.grid[a][b]];const matched=new Set();for(let y=0;y<7;y++)for(let x=0;x<7;x++){const v=s.grid[y][x];if(x<5&&s.grid[y][x+1]===v&&s.grid[y][x+2]===v){for(let q=0;q<3;q++)matched.add(`${y},${x+q}`)}if(y<5&&s.grid[y+1][x]===v&&s.grid[y+2][x]===v){for(let q=0;q<3;q++)matched.add(`${y+q},${x}`)}}s.moves--;if(matched.size){this._score(matched.size*10);for(const key of matched){const[y,x]=key.split(',').map(Number);s.grid[y][x]=Math.floor(Math.random()*5)}if(this.score>=900)this._finish(true);if(s.moves<=0)this._finish(false)}else [s.grid[a][b],s.grid[r][c]]=[s.grid[r][c],s.grid[a][b]];if(s.moves<=0)this._finish(this.score>=900)}s.selected=null}
