 _drawGame(dt){const c=this.ctx,W=this.W,H=this.H,s=this.state,t=this.game.type;if(!W||!H)return;c.clearRect(0,0,W,H);this._background(dt);if(t==='platformer'||t==='runner')this._drawPlatformer(t);else if(t==='shooter'||t==='survival')this._drawCombat(t);else if(['tetris','match3','mines','sliding','connect4','hanoi','tictactoe','pairs','sudoku','wordle'].includes(t))this._drawPuzzle(t);else if(['basketball','penalty','golf','bowling','baseball'].includes(t))this._drawSport(t);else this._drawArcade(t);if(!this.done)this.cb.onScore?.(this.score,this.time)}
